// Package models holds the domain structs of the portfolio CMS. Every struct
// mirrors a table in db_schema.sql one-to-one so repositories stay dumb.
package models

import (
	"errors"
	"time"
)

// ErrNotFound is returned by repositories when a row does not exist. The
// service layer translates it into the right API error.
var ErrNotFound = errors.New("models: not found")

// 2FA methods (admin_2fa.method).
const (
	TwoFAMethodEmailOTP = "EMAIL_OTP"
	TwoFAMethodTOTP     = "TOTP"
)

// OTP purposes (otp_challenges.purpose).
const (
	OTPPurposeLogin2FA      = "LOGIN_2FA"
	OTPPurposePasswordReset = "PASSWORD_RESET"
)

// Audit actions written to audit_log.action.
const (
	AuditLoginSucceeded      = "LOGIN_SUCCEEDED"
	AuditLoginFailed         = "LOGIN_FAILED"
	AuditLoginChallenged     = "LOGIN_CHALLENGED"
	AuditOTPFailed           = "OTP_FAILED"
	AuditOTPResent           = "OTP_RESENT"
	AuditTokenRefreshed      = "TOKEN_REFRESHED"
	AuditTokenReuseDetected  = "TOKEN_REUSE_DETECTED"
	AuditLoggedOut           = "LOGOUT"
	AuditPasswordChanged     = "PASSWORD_CHANGED"
	AuditPasswordReset       = "PASSWORD_RESET"
	AuditPasswordResetAsked  = "PASSWORD_RESET_REQUESTED"
	AuditTwoFAEnabled        = "TWO_FA_ENABLED"
	AuditTwoFADisabled       = "TWO_FA_DISABLED"
	AuditRateLimited         = "RATE_LIMITED"
)

// Audit entity types used by the auth module.
const (
	EntityAdmin = "admin_users"
	EntityAuth  = "auth"
)

// AdminUser maps admin_users.
type AdminUser struct {
	ID           string
	Username     string
	Email        string
	PasswordHash string
	IsActive     bool
	LastLoginAt  *time.Time
	CreatedAt    time.Time
	UpdatedAt    time.Time
}

// TwoFactorConfig maps admin_2fa.
type TwoFactorConfig struct {
	ID          string
	AdminID     string
	Method      string
	TOTPSecret  string
	IsEnabled   bool
	ConfirmedAt *time.Time
	CreatedAt   time.Time
}

// OTPChallenge maps otp_challenges.
type OTPChallenge struct {
	ID           string
	AdminID      string
	OTPHash      string
	Purpose      string
	ExpiresAt    time.Time
	ConsumedAt   *time.Time
	AttemptCount int
	CreatedAt    time.Time
}

// IsExpired reports whether the challenge can no longer be used.
func (c *OTPChallenge) IsExpired(at time.Time) bool { return !at.Before(c.ExpiresAt) }

// IsConsumed reports whether the challenge was already used (or invalidated).
func (c *OTPChallenge) IsConsumed() bool { return c.ConsumedAt != nil }

// RefreshToken maps refresh_tokens. TokenHash is the SHA-256 of the opaque
// token handed to the client; the raw value is never stored.
type RefreshToken struct {
	ID        string
	AdminID   string
	TokenHash string
	ExpiresAt time.Time
	RevokedAt *time.Time
	UserAgent string
	IPAddress string
	CreatedAt time.Time
}

// IsUsable reports whether the token can still be exchanged for a new pair.
func (t *RefreshToken) IsUsable(at time.Time) bool {
	return t.RevokedAt == nil && at.Before(t.ExpiresAt)
}

// AuditEntry maps audit_log.
type AuditEntry struct {
	ID         string
	AdminID    string
	EntityType string
	EntityID   string
	Action     string
	OldValue   string
	NewValue   string
}

// Package apierr defines the single error type the service layer returns and
// the HTTP layer understands. Using one type keeps the mapping from business
// failure to status code + machine-readable code in exactly one place.
package apierr

import (
	"errors"
	"fmt"
	"net/http"
)

// Error is an API-visible error: an HTTP status, a stable machine-readable
// code the frontend can switch on, and a human message.
type Error struct {
	Status  int
	Code    string
	Message string
	Err     error
}

func (e *Error) Error() string {
	if e.Err != nil {
		return fmt.Sprintf("%s: %s: %v", e.Code, e.Message, e.Err)
	}
	return fmt.Sprintf("%s: %s", e.Code, e.Message)
}

func (e *Error) Unwrap() error { return e.Err }

// New builds an error without an underlying cause.
func New(status int, code, message string) *Error {
	return &Error{Status: status, Code: code, Message: message}
}

// Wrap builds an error that keeps the cause for logs while exposing only the
// curated message to clients.
func Wrap(err error, status int, code, message string) *Error {
	return &Error{Status: status, Code: code, Message: message, Err: err}
}

// From extracts the API error from err, or returns nil when err is nil.
// Non-API errors become a generic 500 so internal details never leak.
func From(err error) *Error {
	if err == nil {
		return nil
	}
	var apiErr *Error
	if errors.As(err, &apiErr) {
		return apiErr
	}
	return Wrap(err, http.StatusInternalServerError, "internal_error", "Something went wrong. Please try again.")
}

// BadRequest is a helper for handler-level payload validation.
func BadRequest(code, message string) *Error {
	return New(http.StatusBadRequest, code, message)
}

// Unauthorized is a helper for missing/invalid credentials.
func Unauthorized(code, message string) *Error {
	return New(http.StatusUnauthorized, code, message)
}

// Package ids generates the TEXT primary keys and opaque tokens used across
// the API. Everything comes from crypto/rand — no third-party UUID dependency.
package ids

import (
	"crypto/rand"
	"encoding/base64"
	"encoding/hex"
	"fmt"
)

// New returns a random UUID v4 string (e.g. "9f1c....-....-4...-8...-....").
// All tables in db_schema.sql use TEXT primary keys, so a UUID keeps rows
// sortable, loggable and safe to expose in URLs.
func New() string {
	var b [16]byte
	if _, err := rand.Read(b[:]); err != nil {
		// crypto/rand never fails on supported platforms; if it does, the
		// process cannot safely mint IDs, so fail fast.
		panic(fmt.Errorf("ids: crypto/rand failed: %w", err))
	}
	b[6] = (b[6] & 0x0f) | 0x40 // version 4
	b[8] = (b[8] & 0x3f) | 0x80 // RFC 4122 variant
	return fmt.Sprintf("%x-%x-%x-%x-%x", b[0:4], b[4:6], b[6:8], b[8:10], b[10:16])
}

// NewToken returns a URL-safe random token of nBytes of entropy.
func NewToken(nBytes int) (string, error) {
	b := make([]byte, nBytes)
	if _, err := rand.Read(b); err != nil {
		return "", fmt.Errorf("ids: crypto/rand failed: %w", err)
	}
	return base64.RawURLEncoding.EncodeToString(b), nil
}

// NewHex returns a random hex string of nBytes bytes.
func NewHex(nBytes int) (string, error) {
	b := make([]byte, nBytes)
	if _, err := rand.Read(b); err != nil {
		return "", fmt.Errorf("ids: crypto/rand failed: %w", err)
	}
	return hex.EncodeToString(b), nil
}

package database

import (
	"database/sql"
	"strings"
	"time"
)

// SQLiteTimeLayout is the text format SQLite's datetime('now') produces —
// which is what every DEFAULT in db_schema.sql uses. All timestamps written
// by the API use the same fixed-width UTC layout so that lexicographic
// string comparison in SQL is also chronological comparison.
const SQLiteTimeLayout = "2006-01-02 15:04:05"

// FormatTime renders t as a UTC SQLite datetime string.
func FormatTime(t time.Time) string {
	return t.UTC().Format(SQLiteTimeLayout)
}

// FormatTimePtr renders a nullable timestamp as a driver argument
// (string or nil).
func FormatTimePtr(t *time.Time) any {
	if t == nil {
		return nil
	}
	return FormatTime(*t)
}

// ParseTime parses a SQLite datetime string, tolerating the "T" separator,
// fractional seconds and a trailing "Z" so values written by other tools work.
func ParseTime(s string) (time.Time, error) {
	trimmed := strings.TrimSuffix(strings.TrimSpace(s), "Z")
	layouts := []string{
		SQLiteTimeLayout + ".999999999",
		"2006-01-02T15:04:05.999999999",
		SQLiteTimeLayout,
		"2006-01-02T15:04:05",
		"2006-01-02",
	}
	var err error
	for _, layout := range layouts {
		var t time.Time
		t, err = time.ParseInLocation(layout, trimmed, time.UTC)
		if err == nil {
			return t.UTC(), nil
		}
	}
	return time.Time{}, err
}

// ParseTimePtr parses a nullable datetime column into a *time.Time.
func ParseTimePtr(v sql.NullString) (*time.Time, error) {
	if !v.Valid || strings.TrimSpace(v.String) == "" {
		return nil, nil
	}
	t, err := ParseTime(v.String)
	if err != nil {
		return nil, err
	}
	return &t, nil
}

// ParseTimeValue parses a required datetime column.
func ParseTimeValue(v string) (time.Time, error) {
	return ParseTime(v)
}

// Package security contains the cryptographic primitives of the admin auth
// module: argon2id password hashing, OTP hashing, JWT access tokens, opaque
// refresh tokens and the in-memory login rate limiter.
package security

import (
	"crypto/rand"
	"crypto/subtle"
	"encoding/base64"
	"errors"
	"fmt"
	"strings"

	"golang.org/x/crypto/argon2"
)

// Argon2id parameters. Tuned for a serverless (512 MB) Lambda: 64 MB of memory
// per hash, 3 passes, 2 lanes. They are intentionally hard-coded so hashes
// stay verifiable forever — never change them without a rehash migration.
const (
	argonTime    uint32 = 3
	argonMemory  uint32 = 64 * 1024 // KiB
	argonThreads uint8  = 2
	argonKeyLen  uint32 = 32
	argonSaltLen        = 16
)

// ErrInvalidHash is returned when a stored hash is malformed.
var ErrInvalidHash = errors.New("security: malformed argon2id hash")

// HashPassword derives an argon2id hash encoded as a PHC string:
//
//	$argon2id$v=19$m=65536,t=3,p=2$<salt-b64>$<hash-b64>
func HashPassword(password string) (string, error) {
	return hashSecret(password)
}

// VerifyPassword compares a plaintext password against a stored hash.
// The comparison is constant-time; a malformed hash returns
// ErrInvalidHash so callers can distinguish "bad data" from "wrong password".
func VerifyPassword(encoded, password string) (bool, error) {
	return verifySecret(encoded, password)
}

func hashSecret(secret string) (string, error) {
	salt := make([]byte, argonSaltLen)
	if _, err := rand.Read(salt); err != nil {
		return "", fmt.Errorf("security: salt generation failed: %w", err)
	}
	sum := argon2.IDKey([]byte(secret), salt, argonTime, argonMemory, argonThreads, argonKeyLen)
	return fmt.Sprintf("$argon2id$v=%d$m=%d,t=%d,p=%d$%s$%s",
		argon2.Version, argonMemory, argonTime, argonThreads,
		base64.RawStdEncoding.EncodeToString(salt),
		base64.RawStdEncoding.EncodeToString(sum),
	), nil
}

func verifySecret(encoded, secret string) (bool, error) {
	parts := strings.Split(encoded, "$")
	// ["", "argon2id", "v=19", "m=...,t=...,p=...", salt, hash]
	if len(parts) != 6 || parts[1] != "argon2id" {
		return false, ErrInvalidHash
	}

	var version int
	if _, err := fmt.Sscanf(parts[2], "v=%d", &version); err != nil || version != argon2.Version {
		return false, ErrInvalidHash
	}

	var memory, time2 uint32
	var threads uint8
	if _, err := fmt.Sscanf(parts[3], "m=%d,t=%d,p=%d", &memory, &time2, &threads); err != nil {
		return false, ErrInvalidHash
	}

	salt, err := base64.RawStdEncoding.DecodeString(parts[4])
	if err != nil {
		return false, ErrInvalidHash
	}
	want, err := base64.RawStdEncoding.DecodeString(parts[5])
	if err != nil {
		return false, ErrInvalidHash
	}

	got := argon2.IDKey([]byte(secret), salt, time2, memory, threads, uint32(len(want)))
	return subtle.ConstantTimeCompare(got, want) == 1, nil
}

// NeedsRehash reports whether a stored hash was produced with weaker
// parameters than the current ones, so it can be upgraded on next login.
func NeedsRehash(encoded string) bool {
	parts := strings.Split(encoded, "$")
	if len(parts) != 6 {
		return true
	}
	var memory, time2 uint32
	var threads uint8
	if _, err := fmt.Sscanf(parts[3], "m=%d,t=%d,p=%d", &memory, &time2, &threads); err != nil {
		return true
	}
	return memory != argonMemory || time2 != argonTime || threads != argonThreads
}

// DummyPasswordHash is a valid argon2id hash of a random string. Login runs a
// verification against it when the account does not exist, so the response
// time does not reveal whether a username is registered.
var DummyPasswordHash = mustHash("portfolio-api-dummy-secret")

package security

import (
	"crypto/rand"
	"fmt"
	"math/big"
	"strings"
)

// GenerateOTP returns a random numeric one-time code of the given length.
// The first digit is never zero so the code keeps its full entropy when a
// client trims leading whitespace.
func GenerateOTP(length int) (string, error) {
	if length < 4 || length > 10 {
		return "", fmt.Errorf("security: otp length %d out of range", length)
	}
	digits := make([]byte, length)
	for i := range digits {
		max := big.NewInt(10)
		if i == 0 {
			max = big.NewInt(9) // 1..9
		}
		n, err := rand.Int(rand.Reader, max)
		if err != nil {
			return "", fmt.Errorf("security: otp generation failed: %w", err)
		}
		offset := int64(0)
		if i == 0 {
			offset = 1
		}
		digits[i] = byte('0' + offset + n.Int64())
	}
	return string(digits), nil
}

// HashOTP hashes an OTP with argon2id before it is stored in
// otp_challenges.otp_hash, so a leaked table cannot be replayed.
func HashOTP(code string) (string, error) {
	return hashSecret(code)
}

// VerifyOTP compares a submitted code against the stored otp_hash.
func VerifyOTP(encoded, code string) (bool, error) {
	return verifySecret(encoded, code)
}

// NormalizeOTP trims spaces and interior separators users tend to paste.
func NormalizeOTP(code string) string {
	code = strings.TrimSpace(code)
	code = strings.Map(func(r rune) rune {
		switch r {
		case ' ', '-', '\t', '\n', '\r':
			return -1
		}
		return r
	}, code)
	return code
}

// mustHash is a helper for package-level constants; it panics because a
// failure here means the process cannot hash anything at all.
func mustHash(secret string) string {
	h, err := hashSecret(secret)
	if err != nil {
		panic(err)
	}
	return h
}

package security

import (
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"time"

	"github.com/coderkamlesh/portfolio_api/internal/models"
	"github.com/coderkamlesh/portfolio_api/internal/pkg/ids"
	"github.com/golang-jwt/jwt/v5"
)

// TokenTypeAccess marks a JWT as an access token so a refresh token (which is
// opaque) can never be replayed as a bearer credential.
const TokenTypeAccess = "access"

// RefreshTokenBytes is the entropy of an opaque refresh token.
const RefreshTokenBytes = 32

// ErrInvalidToken is returned for any token that fails signature, type,
// issuer or expiry validation.
var ErrInvalidToken = errors.New("security: invalid token")

// AccessClaims is the JWT payload of an admin access token.
type AccessClaims struct {
	Username string `json:"username"`
	Email    string `json:"email"`
	Type     string `json:"typ"`
	jwt.RegisteredClaims
}

// TokenManager issues and validates access tokens.
type TokenManager struct {
	secret    []byte
	issuer    string
	accessTTL time.Duration
}

// NewTokenManager builds a manager from the JWT_SECRET env value. The secret
// is validated (>= 32 chars) at config load time.
func NewTokenManager(secret, issuer string, accessTTL time.Duration) *TokenManager {
	return &TokenManager{secret: []byte(secret), issuer: issuer, accessTTL: accessTTL}
}

// AccessTTL exposes the configured access-token lifetime (used in responses).
func (m *TokenManager) AccessTTL() time.Duration { return m.accessTTL }

// IssueAccessToken signs a short-lived HS256 access token for the admin.
func (m *TokenManager) IssueAccessToken(admin *models.AdminUser) (string, time.Time, error) {
	now := time.Now().UTC()
	expiresAt := now.Add(m.accessTTL)
	claims := AccessClaims{
		Username: admin.Username,
		Email:    admin.Email,
		Type:     TokenTypeAccess,
		RegisteredClaims: jwt.RegisteredClaims{
			Subject:   admin.ID,
			Issuer:    m.issuer,
			ID:        ids.New(),
			IssuedAt:  jwt.NewNumericDate(now),
			NotBefore: jwt.NewNumericDate(now.Add(-30 * time.Second)),
			ExpiresAt: jwt.NewNumericDate(expiresAt),
		},
	}

	signed, err := jwt.NewWithClaims(jwt.SigningMethodHS256, claims).SignedString(m.secret)
	if err != nil {
		return "", time.Time{}, fmt.Errorf("security: sign access token: %w", err)
	}
	return signed, expiresAt, nil
}

// ParseAccessToken verifies the signature, issuer, expiry and token type and
// returns the claims for the request context.
func (m *TokenManager) ParseAccessToken(raw string) (*AccessClaims, error) {
	claims := &AccessClaims{}
	_, err := jwt.ParseWithClaims(raw, claims, func(t *jwt.Token) (any, error) {
		return m.secret, nil
	},
		jwt.WithValidMethods([]string{jwt.SigningMethodHS256.Alg()}),
		jwt.WithIssuer(m.issuer),
		jwt.WithExpirationRequired(),
	)
	if err != nil {
		return nil, fmt.Errorf("%w: %s", ErrInvalidToken, err)
	}
	if claims.Type != TokenTypeAccess || claims.Subject == "" {
		return nil, fmt.Errorf("%w: unexpected token type", ErrInvalidToken)
	}
	return claims, nil
}

// GenerateRefreshToken returns a fresh opaque refresh token. Only its SHA-256
// hash is persisted, so a database leak cannot be used to impersonate an admin.
func GenerateRefreshToken() (string, error) {
	return ids.NewToken(RefreshTokenBytes)
}

// HashToken hashes an opaque token for storage/lookup.
func HashToken(token string) string {
	sum := sha256.Sum256([]byte(token))
	return hex.EncodeToString(sum[:])
}

package security

import (
	"strings"
	"sync"
	"time"
)

// Limiter is a small in-memory sliding-window counter used to slow down
// password and OTP brute force. It is per-process: behind several Lambda
// instances an attacker gets `instances x max` attempts, which is an accepted
// trade-off for a single-admin panel (no Redis dependency). The database
// based OTP counters (attempt_count, AUTH_OTP_MAX_PER_WINDOW) remain the
// hard limit.
type Limiter struct {
	mu       sync.Mutex
	attempts map[string]*counter
	max      int
	window   time.Duration
	now      func() time.Time
}

type counter struct {
	count   int
	resetAt time.Time
}

// NewLimiter creates a limiter allowing max failures per window.
func NewLimiter(max int, window time.Duration) *Limiter {
	return newLimiterWithClock(max, window, time.Now)
}

func newLimiterWithClock(max int, window time.Duration, now func() time.Time) *Limiter {
	if max < 1 {
		max = 1
	}
	if window <= 0 {
		window = time.Minute
	}
	return &Limiter{attempts: make(map[string]*counter), max: max, window: window, now: now}
}

// Allow reports whether another attempt is permitted for key.
func (l *Limiter) Allow(key string) bool {
	l.mu.Lock()
	defer l.mu.Unlock()
	c, ok := l.attempts[key]
	if !ok {
		return true
	}
	if !l.now().Before(c.resetAt) {
		delete(l.attempts, key)
		return true
	}
	return c.count < l.max
}

// RegisterFailure counts one failed attempt and (re)arms the window.
func (l *Limiter) RegisterFailure(key string) {
	l.mu.Lock()
	defer l.mu.Unlock()
	now := l.now()
	c, ok := l.attempts[key]
	if !ok || !now.Before(c.resetAt) {
		l.attempts[key] = &counter{count: 1, resetAt: now.Add(l.window)}
		l.sweepLocked(now)
		return
	}
	c.count++
}

// Reset clears the counter, e.g. after a successful login.
func (l *Limiter) Reset(key string) {
	l.mu.Lock()
	defer l.mu.Unlock()
	delete(l.attempts, key)
}

// RetryAfter reports how long the caller must wait before the next attempt.
func (l *Limiter) RetryAfter(key string) time.Duration {
	l.mu.Lock()
	defer l.mu.Unlock()
	c, ok := l.attempts[key]
	if !ok {
		return 0
	}
	if d := c.resetAt.Sub(l.now()); d > 0 {
		return d
	}
	return 0
}

// sweepLocked drops expired counters to keep the map bounded on a long-lived
// process. Callers must hold l.mu.
func (l *Limiter) sweepLocked(now time.Time) {
	if len(l.attempts) < 1000 {
		return
	}
	for k, c := range l.attempts {
		if !now.Before(c.resetAt) {
			delete(l.attempts, k)
		}
	}
}

// ClientKey builds a limiter key from an identifier (username/email) and the
// caller IP, so one noisy client cannot lock out an unrelated admin.
func ClientKey(identifier, ip string) string {
	return strings.ToLower(strings.TrimSpace(identifier)) + "|" + ip
}

package security

import "strings"

// MaskEmail hides the local part of an address so OTP screens can confirm
// where the code went without disclosing the full address:
//
//	kamlesh.sharma@gmail.com -> k*************e@gmail.com
func MaskEmail(email string) string {
	at := strings.LastIndex(email, "@")
	if at <= 0 {
		return "***"
	}
	local, domain := email[:at], email[at:]
	switch len(local) {
	case 1:
		return local + "***" + domain
	case 2:
		return local[:1] + "***" + local[1:] + domain
	default:
		return local[:1] + strings.Repeat("*", len(local)-2) + local[len(local)-1:] + domain
	}
}

// Package email delivers transactional mail for the admin panel (currently
// the login OTP and password reset codes) through AWS SES or, in local
// development, to the server log.
package email

import "context"

// Message is a plain transactional mail with an optional HTML alternative.
type Message struct {
	To       string
	Subject  string
	TextBody string
	HTMLBody string
}

// Sender delivers a Message. Implementations must return an error when the
// provider rejects the send so callers can surface a 502 to the client.
type Sender interface {
	Send(ctx context.Context, msg Message) error
}

