package repository

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"time"

	"github.com/coderkamlesh/portfolio_api/internal/database"
	"github.com/coderkamlesh/portfolio_api/internal/models"
)

// TwoFARepository reads and writes admin_2fa.
type TwoFARepository struct {
	base
}

// NewTwoFARepository binds the repository to the database connection.
func NewTwoFARepository(db *database.DB) *TwoFARepository {
	return &TwoFARepository{base{db: db}}
}

const twoFAColumns = `id, admin_id, method, totp_secret, is_enabled, confirmed_at, created_at`

// FindByAdminAndMethod loads the 2FA config for one method, or
// models.ErrNotFound when the admin never enrolled.
func (r *TwoFARepository) FindByAdminAndMethod(ctx context.Context, adminID, method string) (*models.TwoFactorConfig, error) {
	q := `SELECT ` + twoFAColumns + ` FROM admin_2fa WHERE admin_id = ? AND method = ? LIMIT 1`
	cfg, err := scanTwoFA(r.db.QueryRowContext(ctx, q, adminID, method))
	if err != nil {
		return nil, notFound(err)
	}
	return cfg, nil
}

// ListByAdmin returns every 2FA method configured for an admin.
func (r *TwoFARepository) ListByAdmin(ctx context.Context, adminID string) ([]models.TwoFactorConfig, error) {
	q := `SELECT ` + twoFAColumns + ` FROM admin_2fa WHERE admin_id = ? ORDER BY method`
	rows, err := r.db.QueryContext(ctx, q, adminID)
	if err != nil {
		return nil, fmt.Errorf("2fa: list: %w", err)
	}
	defer rows.Close()

	var out []models.TwoFactorConfig
	for rows.Next() {
		cfg, err := scanTwoFA(rows)
		if err != nil {
			return nil, err
		}
		out = append(out, *cfg)
	}
	return out, rows.Err()
}

// Upsert creates or updates the config row for (admin_id, method).
func (r *TwoFARepository) Upsert(ctx context.Context, cfg *models.TwoFactorConfig) error {
	const update = `UPDATE admin_2fa SET is_enabled = ?, confirmed_at = ? WHERE admin_id = ? AND method = ?`
	res, err := r.db.ExecContext(ctx, update,
		boolToInt(cfg.IsEnabled), database.FormatTimePtr(cfg.ConfirmedAt), cfg.AdminID, cfg.Method)
	if err != nil {
		return fmt.Errorf("2fa: upsert update: %w", err)
	}
	if n, err := res.RowsAffected(); err == nil && n > 0 {
		return nil
	}

	const insert = `INSERT INTO admin_2fa (id, admin_id, method, totp_secret, is_enabled, confirmed_at, created_at)
	                VALUES (?, ?, ?, ?, ?, ?, ?)`
	if _, err := r.db.ExecContext(ctx, insert,
		cfg.ID, cfg.AdminID, cfg.Method, nullString(cfg.TOTPSecret), boolToInt(cfg.IsEnabled),
		database.FormatTimePtr(cfg.ConfirmedAt), database.FormatTime(cfg.CreatedAt),
	); err != nil {
		return fmt.Errorf("2fa: upsert insert: %w", err)
	}
	return nil
}

// SetEnabled flips the enabled flag for an existing row and returns
// models.ErrNotFound when the admin has no such method configured.
func (r *TwoFARepository) SetEnabled(ctx context.Context, adminID, method string, enabled bool, at time.Time) error {
	const q = `UPDATE admin_2fa SET is_enabled = ?, confirmed_at = ? WHERE admin_id = ? AND method = ?`
	res, err := r.db.ExecContext(ctx, q, boolToInt(enabled), database.FormatTimePtr(&at), adminID, method)
	if err != nil {
		return fmt.Errorf("2fa: set enabled: %w", err)
	}
	n, err := res.RowsAffected()
	if err != nil {
		return fmt.Errorf("2fa: set enabled rows: %w", err)
	}
	if n == 0 {
		return models.ErrNotFound
	}
	return nil
}

func scanTwoFA(row rowScanner) (*models.TwoFactorConfig, error) {
	var (
		cfg         models.TwoFactorConfig
		secret      sql.NullString
		enabled     sql.NullInt64
		confirmedAt sql.NullString
		createdAt   string
	)
	if err := row.Scan(&cfg.ID, &cfg.AdminID, &cfg.Method, &secret, &enabled, &confirmedAt, &createdAt); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, models.ErrNotFound
		}
		return nil, fmt.Errorf("2fa: scan: %w", err)
	}
	cfg.TOTPSecret = secret.String
	cfg.IsEnabled = boolFromInt(enabled)

	confirmed, err := database.ParseTimePtr(confirmedAt)
	if err != nil {
		return nil, fmt.Errorf("2fa: parse confirmed_at: %w", err)
	}
	cfg.ConfirmedAt = confirmed

	if cfg.CreatedAt, err = database.ParseTime(createdAt); err != nil {
		return nil, fmt.Errorf("2fa: parse created_at: %w", err)
	}
	return &cfg, nil
}

// nullString turns an empty string into a SQL NULL so optional columns stay
// nullable (totp_secret is unused for EMAIL_OTP).
func nullString(v string) any {
	if v == "" {
		return nil
	}
	return v
}

package repository

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"time"

	"github.com/coderkamlesh/portfolio_api/internal/database"
	"github.com/coderkamlesh/portfolio_api/internal/models"
)

// OTPRepository reads and writes otp_challenges.
type OTPRepository struct {
	base
}

// NewOTPRepository binds the repository to the database connection.
func NewOTPRepository(db *database.DB) *OTPRepository {
	return &OTPRepository{base{db: db}}
}

const otpColumns = `id, admin_id, otp_hash, purpose, expires_at, consumed_at, attempt_count, created_at`

// Create stores a new challenge.
func (r *OTPRepository) Create(ctx context.Context, c *models.OTPChallenge) error {
	const q = `INSERT INTO otp_challenges (id, admin_id, otp_hash, purpose, expires_at, consumed_at, attempt_count, created_at)
	           VALUES (?, ?, ?, ?, ?, NULL, 0, ?)`
	_, err := r.db.ExecContext(ctx, q, c.ID, c.AdminID, c.OTPHash, c.Purpose,
		database.FormatTime(c.ExpiresAt), database.FormatTime(c.CreatedAt))
	if err != nil {
		return fmt.Errorf("otp: create: %w", err)
	}
	return nil
}

// FindByID loads a challenge by id.
func (r *OTPRepository) FindByID(ctx context.Context, id string) (*models.OTPChallenge, error) {
	q := `SELECT ` + otpColumns + ` FROM otp_challenges WHERE id = ? LIMIT 1`
	c, err := scanOTP(r.db.QueryRowContext(ctx, q, id))
	if err != nil {
		return nil, notFound(err)
	}
	return c, nil
}

// FindLatestPending returns the newest unconsumed challenge of a purpose for
// an admin — used to enforce the resend cooldown.
func (r *OTPRepository) FindLatestPending(ctx context.Context, adminID, purpose string, at time.Time) (*models.OTPChallenge, error) {
	q := `SELECT ` + otpColumns + ` FROM otp_challenges
	      WHERE admin_id = ? AND purpose = ? AND consumed_at IS NULL AND expires_at > ?
	      ORDER BY created_at DESC LIMIT 1`
	c, err := scanOTP(r.db.QueryRowContext(ctx, q, adminID, purpose, database.FormatTime(at)))
	if err != nil {
		return nil, notFound(err)
	}
	return c, nil
}

// CountCreatedSince counts challenges of a purpose issued after `since`, which
// caps how many mails an attacker can trigger for one account.
func (r *OTPRepository) CountCreatedSince(ctx context.Context, adminID, purpose string, since time.Time) (int, error) {
	q := `SELECT COUNT(*) FROM otp_challenges WHERE admin_id = ? AND purpose = ? AND created_at >= ?`
	var n int
	if err := r.db.QueryRowContext(ctx, q, adminID, purpose, database.FormatTime(since)).Scan(&n); err != nil {
		return 0, fmt.Errorf("otp: count since: %w", err)
	}
	return n, nil
}

// InvalidatePending consumes every pending challenge of a purpose, so only the
// most recent code can ever be used.
func (r *OTPRepository) InvalidatePending(ctx context.Context, adminID, purpose string, at time.Time) error {
	const q = `UPDATE otp_challenges SET consumed_at = ? WHERE admin_id = ? AND purpose = ? AND consumed_at IS NULL`
	if _, err := r.db.ExecContext(ctx, q, database.FormatTime(at), adminID, purpose); err != nil {
		return fmt.Errorf("otp: invalidate pending: %w", err)
	}
	return nil
}

// IncrementAttempts bumps attempt_count and returns the new value.
func (r *OTPRepository) IncrementAttempts(ctx context.Context, id string) (int, error) {
	const q = `UPDATE otp_challenges SET attempt_count = attempt_count + 1 WHERE id = ?`
	if _, err := r.db.ExecContext(ctx, q, id); err != nil {
		return 0, fmt.Errorf("otp: increment attempts: %w", err)
	}
	var attempts int
	if err := r.db.QueryRowContext(ctx, `SELECT attempt_count FROM otp_challenges WHERE id = ?`, id).Scan(&attempts); err != nil {
		return 0, fmt.Errorf("otp: read attempts: %w", err)
	}
	return attempts, nil
}

// Consume marks a challenge as used in a single conditional UPDATE, which
// makes the OTP one-shot even when two requests race.
func (r *OTPRepository) Consume(ctx context.Context, id string, at time.Time) (bool, error) {
	const q = `UPDATE otp_challenges SET consumed_at = ? WHERE id = ? AND consumed_at IS NULL`
	res, err := r.db.ExecContext(ctx, q, database.FormatTime(at), id)
	if err != nil {
		return false, fmt.Errorf("otp: consume: %w", err)
	}
	n, err := res.RowsAffected()
	if err != nil {
		return false, fmt.Errorf("otp: consume rows: %w", err)
	}
	return n > 0, nil
}

// DeleteOlderThan prunes finished challenges; called best-effort so the table
// does not grow forever.
func (r *OTPRepository) DeleteOlderThan(ctx context.Context, before time.Time) error {
	const q = `DELETE FROM otp_challenges WHERE created_at < ? AND (consumed_at IS NOT NULL OR expires_at < ?)`
	if _, err := r.db.ExecContext(ctx, q, database.FormatTime(before), database.FormatTime(before)); err != nil {
		return fmt.Errorf("otp: prune: %w", err)
	}
	return nil
}

func scanOTP(row rowScanner) (*models.OTPChallenge, error) {
	var (
		c          models.OTPChallenge
		expiresAt  string
		consumedAt sql.NullString
		createdAt  string
		attempts   sql.NullInt64
	)
	if err := row.Scan(&c.ID, &c.AdminID, &c.OTPHash, &c.Purpose, &expiresAt, &consumedAt, &attempts, &createdAt); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, models.ErrNotFound
		}
		return nil, fmt.Errorf("otp: scan: %w", err)
	}
	c.AttemptCount = int(attempts.Int64)

	var err error
	if c.ExpiresAt, err = database.ParseTime(expiresAt); err != nil {
		return nil, fmt.Errorf("otp: parse expires_at: %w", err)
	}
	if c.ConsumedAt, err = database.ParseTimePtr(consumedAt); err != nil {
		return nil, fmt.Errorf("otp: parse consumed_at: %w", err)
	}
	if c.CreatedAt, err = database.ParseTime(createdAt); err != nil {
		return nil, fmt.Errorf("otp: parse created_at: %w", err)
	}
	return &c, nil
}

package repository

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"time"

	"github.com/coderkamlesh/portfolio_api/internal/database"
	"github.com/coderkamlesh/portfolio_api/internal/models"
)

// RefreshTokenRepository reads and writes refresh_tokens.
type RefreshTokenRepository struct {
	base
}

// NewRefreshTokenRepository binds the repository to the database connection.
func NewRefreshTokenRepository(db *database.DB) *RefreshTokenRepository {
	return &RefreshTokenRepository{base{db: db}}
}

const refreshColumns = `id, admin_id, token_hash, expires_at, revoked_at, user_agent, ip_address, created_at`

// Create stores the hash of a freshly minted refresh token.
func (r *RefreshTokenRepository) Create(ctx context.Context, t *models.RefreshToken) error {
	const q = `INSERT INTO refresh_tokens (id, admin_id, token_hash, expires_at, revoked_at, user_agent, ip_address, created_at)
	           VALUES (?, ?, ?, ?, NULL, ?, ?, ?)`
	_, err := r.db.ExecContext(ctx, q, t.ID, t.AdminID, t.TokenHash, database.FormatTime(t.ExpiresAt),
		nullString(t.UserAgent), nullString(t.IPAddress), database.FormatTime(t.CreatedAt))
	if err != nil {
		return fmt.Errorf("refresh: create: %w", err)
	}
	return nil
}

// FindByHash loads a token by its SHA-256 hash.
func (r *RefreshTokenRepository) FindByHash(ctx context.Context, tokenHash string) (*models.RefreshToken, error) {
	q := `SELECT ` + refreshColumns + ` FROM refresh_tokens WHERE token_hash = ? LIMIT 1`
	t, err := scanRefresh(r.db.QueryRowContext(ctx, q, tokenHash))
	if err != nil {
		return nil, notFound(err)
	}
	return t, nil
}

// Revoke marks a single token as revoked. It returns false when the token was
// already revoked (or never existed).
func (r *RefreshTokenRepository) Revoke(ctx context.Context, id string, at time.Time) (bool, error) {
	const q = `UPDATE refresh_tokens SET revoked_at = ? WHERE id = ? AND revoked_at IS NULL`
	res, err := r.db.ExecContext(ctx, q, database.FormatTime(at), id)
	if err != nil {
		return false, fmt.Errorf("refresh: revoke: %w", err)
	}
	n, err := res.RowsAffected()
	if err != nil {
		return false, fmt.Errorf("refresh: revoke rows: %w", err)
	}
	return n > 0, nil
}

// RevokeAllForAdmin kills every active session of an admin. Used on logout-all,
// password change/reset and when refresh-token reuse is detected.
func (r *RefreshTokenRepository) RevokeAllForAdmin(ctx context.Context, adminID string, at time.Time) (int64, error) {
	const q = `UPDATE refresh_tokens SET revoked_at = ? WHERE admin_id = ? AND revoked_at IS NULL`
	res, err := r.db.ExecContext(ctx, q, database.FormatTime(at), adminID)
	if err != nil {
		return 0, fmt.Errorf("refresh: revoke all: %w", err)
	}
	n, err := res.RowsAffected()
	if err != nil {
		return 0, fmt.Errorf("refresh: revoke all rows: %w", err)
	}
	return n, nil
}

// CountActive returns how many sessions an admin currently has.
func (r *RefreshTokenRepository) CountActive(ctx context.Context, adminID string, at time.Time) (int, error) {
	const q = `SELECT COUNT(*) FROM refresh_tokens WHERE admin_id = ? AND revoked_at IS NULL AND expires_at > ?`
	var n int
	if err := r.db.QueryRowContext(ctx, q, adminID, database.FormatTime(at)).Scan(&n); err != nil {
		return 0, fmt.Errorf("refresh: count active: %w", err)
	}
	return n, nil
}

// DeleteExpired prunes tokens that expired long ago (best-effort housekeeping).
func (r *RefreshTokenRepository) DeleteExpired(ctx context.Context, before time.Time) error {
	const q = `DELETE FROM refresh_tokens WHERE expires_at < ?`
	if _, err := r.db.ExecContext(ctx, q, database.FormatTime(before)); err != nil {
		return fmt.Errorf("refresh: prune: %w", err)
	}
	return nil
}

func scanRefresh(row rowScanner) (*models.RefreshToken, error) {
	var (
		t         models.RefreshToken
		expiresAt string
		revokedAt sql.NullString
		userAgent sql.NullString
		ip        sql.NullString
		createdAt string
	)
	if err := row.Scan(&t.ID, &t.AdminID, &t.TokenHash, &expiresAt, &revokedAt, &userAgent, &ip, &createdAt); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, models.ErrNotFound
		}
		return nil, fmt.Errorf("refresh: scan: %w", err)
	}
	t.UserAgent = userAgent.String
	t.IPAddress = ip.String

	var err error
	if t.ExpiresAt, err = database.ParseTime(expiresAt); err != nil {
		return nil, fmt.Errorf("refresh: parse expires_at: %w", err)
	}
	if t.RevokedAt, err = database.ParseTimePtr(revokedAt); err != nil {
		return nil, fmt.Errorf("refresh: parse revoked_at: %w", err)
	}
	if t.CreatedAt, err = database.ParseTime(createdAt); err != nil {
		return nil, fmt.Errorf("refresh: parse created_at: %w", err)
	}
	return &t, nil
}

