package service

import (
	"context"
	"errors"
	"log"

	"github.com/coderkamlesh/portfolio_api/internal/models"
	"github.com/coderkamlesh/portfolio_api/internal/pkg/ids"
	"github.com/coderkamlesh/portfolio_api/internal/security"
)

// issueSession mints an access token plus a rotating opaque refresh token.
// Only the SHA-256 hash of the refresh token is persisted.
func (s *AuthService) issueSession(ctx context.Context, admin *models.AdminUser, meta RequestMeta) (*TokenPair, error) {
	accessToken, accessExpiresAt, err := s.tokens.IssueAccessToken(admin)
	if err != nil {
		return nil, wrapErr(err, 500, "internal_error", "Could not create a session.")
	}

	refreshToken, err := security.GenerateRefreshToken()
	if err != nil {
		return nil, wrapErr(err, 500, "internal_error", "Could not create a session.")
	}

	now := s.now()
	refreshExpiresAt := now.Add(s.cfg.RefreshTokenTTL)
	record := &models.RefreshToken{
		ID:        ids.New(),
		AdminID:   admin.ID,
		TokenHash: security.HashToken(refreshToken),
		ExpiresAt: refreshExpiresAt,
		UserAgent: sanitizeUserAgent(meta.UserAgent),
		IPAddress: meta.IPAddress,
		CreatedAt: now,
	}
	if err := s.refresh.Create(ctx, record); err != nil {
		return nil, err
	}

	return &TokenPair{
		TokenType:        "Bearer",
		AccessToken:      accessToken,
		ExpiresIn:        int(s.tokens.AccessTTL().Seconds()),
		ExpiresAt:        accessExpiresAt,
		RefreshToken:     refreshToken,
		RefreshExpiresIn: int(s.cfg.RefreshTokenTTL.Seconds()),
		RefreshExpiresAt: refreshExpiresAt,
	}, nil
}

// Refresh rotates a refresh token: the presented token is revoked and a fresh
// pair is issued. Replaying an already-revoked token revokes every session of
// that admin, which is the standard protection against a stolen token.
func (s *AuthService) Refresh(ctx context.Context, in RefreshInput, meta RequestMeta) (*LoginResult, error) {
	if in.RefreshToken == "" {
		return nil, errInvalidRefreshToken()
	}

	record, err := s.refresh.FindByHash(ctx, security.HashToken(in.RefreshToken))
	if err != nil {
		if errors.Is(err, models.ErrNotFound) {
			return nil, errInvalidRefreshToken()
		}
		return nil, err
	}

	now := s.now()

	if record.RevokedAt != nil {
		s.revokeAllSessions(ctx, record.AdminID, "refresh_token_reuse")
		return nil, errRefreshTokenReused()
	}
	if !now.Before(record.ExpiresAt) {
		if _, err := s.refresh.Revoke(ctx, record.ID, now); err != nil {
			log.Printf("⚠️  auth: could not revoke expired token %s: %v", record.ID, err)
		}
		return nil, errInvalidRefreshToken()
	}

	admin, err := s.adminFor(ctx, record.AdminID)
	if err != nil {
		return nil, err
	}
	if !admin.IsActive {
		s.revokeAllSessions(ctx, admin.ID, "account_disabled")
		return nil, errAccountDisabled()
	}

	rotated, err := s.refresh.Revoke(ctx, record.ID, now)
	if err != nil {
		return nil, err
	}
	if !rotated {
		// Someone else rotated it a moment ago — treat as reuse.
		s.revokeAllSessions(ctx, admin.ID, "refresh_token_race")
		return nil, errRefreshTokenReused()
	}

	tokens, err := s.issueSession(ctx, admin, meta)
	if err != nil {
		return nil, err
	}
	s.auditEvent(ctx, admin.ID, models.AuditTokenRefreshed, "", nil)
	return &LoginResult{Tokens: tokens, Admin: adminView(admin)}, nil
}

// Logout revokes one session, or every session of the admin.
func (s *AuthService) Logout(ctx context.Context, adminID string, in LogoutInput) error {
	now := s.now()

	if in.AllDevices || in.RefreshToken == "" {
		if _, err := s.refresh.RevokeAllForAdmin(ctx, adminID, now); err != nil {
			return err
		}
		s.auditEvent(ctx, adminID, models.AuditLoggedOut, "all_devices", nil)
		return nil
	}

	record, err := s.refresh.FindByHash(ctx, security.HashToken(in.RefreshToken))
	if err != nil {
		if errors.Is(err, models.ErrNotFound) {
			return nil // already gone — logging out is idempotent
		}
		return err
	}
	if record.AdminID != adminID {
		return errInvalidRefreshToken()
	}
	if _, err := s.refresh.Revoke(ctx, record.ID, now); err != nil {
		return err
	}
	s.auditEvent(ctx, adminID, models.AuditLoggedOut, "single_device", nil)
	return nil
}

// CurrentAdmin powers GET /api/auth/me.
func (s *AuthService) CurrentAdmin(ctx context.Context, adminID string) (*MeView, error) {
	admin, err := s.admins.FindByID(ctx, adminID)
	if err != nil {
		if errors.Is(err, models.ErrNotFound) {
			return nil, errInvalidRefreshToken()
		}
		return nil, err
	}
	if !admin.IsActive {
		return nil, errAccountDisabled()
	}

	status, err := s.TwoFAStatus(ctx, admin)
	if err != nil {
		return nil, err
	}
	sessions, err := s.refresh.CountActive(ctx, admin.ID, s.now())
	if err != nil {
		log.Printf("⚠️  auth: could not count sessions for %s: %v", admin.ID, err)
		sessions = 0
	}

	return &MeView{Admin: adminView(admin), TwoFactor: status, ActiveSession: sessions}, nil
}

// revokeAllSessions revokes every refresh token of the admin and records why.
func (s *AuthService) revokeAllSessions(ctx context.Context, adminID, reason string) {
	if _, err := s.refresh.RevokeAllForAdmin(ctx, adminID, s.now()); err != nil {
		log.Printf("⚠️  auth: revoke all sessions failed for %s: %v", adminID, err)
	}
	s.auditEvent(ctx, adminID, models.AuditTokenReuseDetected, reason, nil)
}

package service

import (
	"context"
	"errors"
	"log"

	"github.com/coderkamlesh/portfolio_api/internal/models"
	"github.com/coderkamlesh/portfolio_api/internal/pkg/ids"
	"github.com/coderkamlesh/portfolio_api/internal/security"
)

// emailTwoFAConfig resolves whether email OTP must be used for this admin.
//
// Rules:
//   - a row with is_enabled = 1 means 2FA is on;
//   - when AUTH_2FA_REQUIRED=true the second factor can never be skipped: a
//     missing row is auto-provisioned (no enrollment is needed for email OTP)
//     and a disabled row is re-enabled;
//   - when AUTH_2FA_REQUIRED=false the admin's own setting decides.
//
// The bool return value reports whether an OTP must be sent.
func (s *AuthService) emailTwoFAConfig(ctx context.Context, admin *models.AdminUser) (*models.TwoFactorConfig, bool, error) {
	cfg, err := s.twoFA.FindByAdminAndMethod(ctx, admin.ID, models.TwoFAMethodEmailOTP)
	switch {
	case err == nil:
		if cfg.IsEnabled {
			return cfg, true, nil
		}
		if !s.cfg.TwoFARequired {
			return cfg, false, nil
		}

		now := s.now()
		cfg.IsEnabled = true
		cfg.ConfirmedAt = &now
		if err := s.twoFA.SetEnabled(ctx, admin.ID, cfg.Method, true, now); err != nil {
			return nil, false, err
		}
		s.auditEvent(ctx, admin.ID, models.AuditTwoFAEnabled, "enforced_by_config", nil)
		return cfg, true, nil

	case errors.Is(err, models.ErrNotFound):
		if !s.cfg.TwoFARequired {
			return nil, false, nil
		}
		now := s.now()
		cfg = &models.TwoFactorConfig{
			ID:          ids.New(),
			AdminID:     admin.ID,
			Method:      models.TwoFAMethodEmailOTP,
			IsEnabled:   true,
			ConfirmedAt: &now,
			CreatedAt:   now,
		}
		if err := s.twoFA.Upsert(ctx, cfg); err != nil {
			return nil, false, err
		}
		s.auditEvent(ctx, admin.ID, models.AuditTwoFAEnabled, "auto_provisioned", nil)
		return cfg, true, nil

	default:
		return nil, false, err
	}
}

// TwoFAStatus reports the effective 2FA state: Enabled is true when the
// second factor is required either by server policy or by the admin setting.
func (s *AuthService) TwoFAStatus(ctx context.Context, admin *models.AdminUser) (*TwoFAStatus, error) {
	status := &TwoFAStatus{
		Required: s.cfg.TwoFARequired,
		Method:   models.TwoFAMethodEmailOTP,
		Email:    security.MaskEmail(admin.Email),
	}

	cfg, err := s.twoFA.FindByAdminAndMethod(ctx, admin.ID, models.TwoFAMethodEmailOTP)
	if err != nil {
		if errors.Is(err, models.ErrNotFound) {
			status.Enabled = s.cfg.TwoFARequired
			return status, nil
		}
		return nil, err
	}

	status.Enabled = cfg.IsEnabled || s.cfg.TwoFARequired
	status.ConfirmedAt = cfg.ConfirmedAt
	created := cfg.CreatedAt
	status.UpdatedAt = &created
	return status, nil
}

// TwoFAStatusByAdminID is the handler-friendly variant of TwoFAStatus.
func (s *AuthService) TwoFAStatusByAdminID(ctx context.Context, adminID string) (*TwoFAStatus, error) {
	admin, err := s.adminFor(ctx, adminID)
	if err != nil {
		return nil, err
	}
	return s.TwoFAStatus(ctx, admin)
}

// EnableEmailOTP turns the email second factor on (password re-confirmation
// required) and returns the fresh status.
func (s *AuthService) EnableEmailOTP(ctx context.Context, adminID string, in PasswordConfirmationInput) (*TwoFAStatus, error) {
	admin, err := s.verifyAdminPassword(ctx, adminID, in.Password)
	if err != nil {
		return nil, err
	}

	now := s.now()
	cfg := &models.TwoFactorConfig{
		ID:          ids.New(),
		AdminID:     admin.ID,
		Method:      models.TwoFAMethodEmailOTP,
		IsEnabled:   true,
		ConfirmedAt: &now,
		CreatedAt:   now,
	}
	if err := s.twoFA.Upsert(ctx, cfg); err != nil {
		return nil, err
	}
	s.auditEvent(ctx, admin.ID, models.AuditTwoFAEnabled, "admin_setting", nil)
	return s.TwoFAStatus(ctx, admin)
}

// DisableEmailOTP turns the second factor off. It refuses when the server
// enforces 2FA (AUTH_2FA_REQUIRED=true) so a compromised session cannot strip
// the protection.
func (s *AuthService) DisableEmailOTP(ctx context.Context, adminID string, in PasswordConfirmationInput) error {
	if s.cfg.TwoFARequired {
		return errTwoFAEnforced()
	}

	admin, err := s.verifyAdminPassword(ctx, adminID, in.Password)
	if err != nil {
		return err
	}

	if err := s.twoFA.SetEnabled(ctx, admin.ID, models.TwoFAMethodEmailOTP, false, s.now()); err != nil {
		if errors.Is(err, models.ErrNotFound) {
			return errTwoFANotConfigured()
		}
		return err
	}
	s.auditEvent(ctx, admin.ID, models.AuditTwoFADisabled, "admin_setting", nil)
	return nil
}

// verifyAdminPassword re-authenticates a signed-in admin for sensitive actions.
func (s *AuthService) verifyAdminPassword(ctx context.Context, adminID, password string) (*models.AdminUser, error) {
	admin, err := s.admins.FindByID(ctx, adminID)
	if err != nil {
		if errors.Is(err, models.ErrNotFound) {
			return nil, errInvalidCredentials()
		}
		return nil, err
	}
	if !admin.IsActive {
		return nil, errAccountDisabled()
	}
	if password == "" {
		return nil, errInvalidPassword()
	}

	ok, err := security.VerifyPassword(admin.PasswordHash, password)
	if err != nil {
		return nil, wrapErr(err, 500, "internal_error", "Stored credentials are unreadable.")
	}
	if !ok {
		log.Printf("⚠️  auth: password re-confirmation failed for admin %s", admin.ID)
		return nil, errInvalidPassword()
	}
	return admin, nil
}

package service

import (
	"context"
	"errors"
	"fmt"
	"log"
	"strings"
	"unicode"

	"github.com/coderkamlesh/portfolio_api/internal/models"
	"github.com/coderkamlesh/portfolio_api/internal/security"
)

// ChangePassword rotates the password of the signed-in admin. Every other
// session is revoked and a fresh pair is returned so the caller stays signed
// in on the current device.
func (s *AuthService) ChangePassword(ctx context.Context, adminID string, in ChangePasswordInput, meta RequestMeta) (*TokenPair, error) {
	if err := s.validatePassword(in.NewPassword); err != nil {
		return nil, err
	}

	admin, err := s.verifyAdminPassword(ctx, adminID, in.CurrentPassword)
	if err != nil {
		return nil, err
	}

	same, err := security.VerifyPassword(admin.PasswordHash, in.NewPassword)
	if err != nil {
		return nil, wrapErr(err, 500, "internal_error", "Stored credentials are unreadable.")
	}
	if same {
		return nil, errSamePassword()
	}

	hash, err := security.HashPassword(in.NewPassword)
	if err != nil {
		return nil, wrapErr(err, 500, "internal_error", "Could not store the new password.")
	}
	if err := s.admins.UpdatePassword(ctx, admin.ID, hash, s.now()); err != nil {
		return nil, err
	}

	// Kill every existing session, then start a new one for this device.
	if _, err := s.refresh.RevokeAllForAdmin(ctx, admin.ID, s.now()); err != nil {
		log.Printf("⚠️  auth: could not revoke sessions after password change: %v", err)
	}
	tokens, err := s.issueSession(ctx, admin, meta)
	if err != nil {
		return nil, err
	}

	s.auditEvent(ctx, admin.ID, models.AuditPasswordChanged, "", nil)
	return tokens, nil
}

// ForgotPassword mails a reset code. It always reports success so the endpoint
// cannot be used to enumerate admin email addresses.
func (s *AuthService) ForgotPassword(ctx context.Context, in ForgotPasswordInput, meta RequestMeta) error {
	emailAddress := strings.ToLower(strings.TrimSpace(in.Email))
	if emailAddress == "" {
		return nil
	}

	admin, err := s.admins.FindByIdentifier(ctx, emailAddress)
	if err != nil {
		if errors.Is(err, models.ErrNotFound) {
			log.Printf("🔐 auth: password reset requested for unknown address %s", emailAddress)
			return nil
		}
		return err
	}
	if !admin.IsActive {
		return nil
	}

	if _, err := s.issueOTP(ctx, admin, models.OTPPurposePasswordReset, meta); err != nil {
		// Rate limiting is the only failure worth surfacing; mail problems are
		// reported as success to keep the response indistinguishable.
		var apiErr *apierr.Error
		if errors.As(err, &apiErr) && apiErr.Status == 429 {
			return err
		}
		log.Printf("⚠️  auth: reset mail failed for admin %s: %v", admin.ID, err)
		return nil
	}
	s.auditEvent(ctx, admin.ID, models.AuditPasswordResetAsked, "", nil)
	return nil
}

// ResetPassword completes the reset flow and signs the admin in.
func (s *AuthService) ResetPassword(ctx context.Context, in ResetPasswordInput, meta RequestMeta) (*LoginResult, error) {
	if err := s.validatePassword(in.NewPassword); err != nil {
		return nil, err
	}

	challenge, err := s.loadChallenge(ctx, in.ChallengeID, models.OTPPurposePasswordReset)
	if err != nil {
		return nil, err
	}

	admin, err := s.checkOTP(ctx, challenge, in.OTP)
	if err != nil {
		return nil, err
	}

	hash, err := security.HashPassword(in.NewPassword)
	if err != nil {
		return nil, wrapErr(err, 500, "internal_error", "Could not store the new password.")
	}
	if err := s.admins.UpdatePassword(ctx, admin.ID, hash, s.now()); err != nil {
		return nil, err
	}
	if _, err := s.refresh.RevokeAllForAdmin(ctx, admin.ID, s.now()); err != nil {
		log.Printf("⚠️  auth: could not revoke sessions after password reset: %v", err)
	}
	if err := s.admins.TouchLastLogin(ctx, admin.ID, s.now()); err != nil {
		log.Printf("⚠️  auth: could not record last login for admin %s: %v", admin.ID, err)
	}

	tokens, err := s.issueSession(ctx, admin, meta)
	if err != nil {
		return nil, err
	}
	s.auditEvent(ctx, admin.ID, models.AuditPasswordReset, "", nil)
	return &LoginResult{Tokens: tokens, Admin: adminView(admin)}, nil
}

// validatePassword enforces the password policy (AUTH_MIN_PASSWORD_LENGTH plus
// a basic mix requirement). Passphrases are welcome — no symbol zoo needed.
func (s *AuthService) validatePassword(password string) error {
	if len(password) < s.cfg.MinPasswordLength {
		return errWeakPassword(fmt.Sprintf("Password must be at least %d characters long.", s.cfg.MinPasswordLength))
	}
	if len(password) > 256 {
		return errWeakPassword("Password must be at most 256 characters long.")
	}

	var hasLetter, hasDigitOrSymbol bool
	for _, r := range password {
		switch {
		case unicode.IsLetter(r):
			hasLetter = true
		case unicode.IsDigit(r), unicode.IsPunct(r), unicode.IsSymbol(r), unicode.IsSpace(r):
			hasDigitOrSymbol = true
		}
	}
	if !hasLetter || !hasDigitOrSymbol {
		return errWeakPassword("Password must mix letters with numbers, symbols or spaces.")
	}
	return nil
}

// Package handler exposes the auth service over HTTP (chi). Handlers only
// decode/validate the request, call the service and encode the response —
// all rules live in the service layer.
package handler

import (
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"log"
	"net"
	"net/http"
	"strconv"
	"strings"

	"github.com/coderkamlesh/portfolio_api/internal/apierr"
	"github.com/coderkamlesh/portfolio_api/internal/service"
)

// maxBodyBytes caps request bodies — auth payloads are tiny.
const maxBodyBytes = 64 * 1024

// errorEnvelope is the shape of every failed response:
//
//	{"error": {"code": "invalid_credentials", "message": "…"}}
type errorEnvelope struct {
	Error errorBody `json:"error"`
}

type errorBody struct {
	Code    string `json:"code"`
	Message string `json:"message"`
}

// writeJSON serialises payload with the given status code.
func writeJSON(w http.ResponseWriter, status int, payload any) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.Header().Set("Cache-Control", "no-store")
	w.WriteHeader(status)
	if payload == nil {
		return
	}
	if err := json.NewEncoder(w).Encode(payload); err != nil {
		log.Printf("⚠️  handler: encode response failed: %v", err)
	}
}

// writeNoContent answers 204.
func writeNoContent(w http.ResponseWriter) {
	w.Header().Set("Cache-Control", "no-store")
	w.WriteHeader(http.StatusNoContent)
}

// writeErr maps any error to the JSON error envelope. Internal errors are
// logged with their cause but never exposed.
func writeErr(w http.ResponseWriter, r *http.Request, err error) {
	apiErr := apierr.From(err)
	if apiErr.Status >= http.StatusInternalServerError {
		log.Printf("❌ handler: %s %s -> %d %s: %v", r.Method, r.URL.Path, apiErr.Status, apiErr.Code, apiErr.Err)
	}
	if apiErr.RetryAfter > 0 {
		w.Header().Set("Retry-After", strconv.Itoa(apiErr.RetryAfter))
	}
	writeJSON(w, apiErr.Status, errorEnvelope{Error: errorBody{Code: apiErr.Code, Message: apiErr.Message}})
}

// decodeJSON reads a single JSON object with strict field checking.
func decodeJSON(w http.ResponseWriter, r *http.Request, dst any) error {
	r.Body = http.MaxBytesReader(w, r.Body, maxBodyBytes)

	decoder := json.NewDecoder(r.Body)
	decoder.DisallowUnknownFields()

	if err := decoder.Decode(dst); err != nil {
		switch {
		case errors.Is(err, io.EOF):
			return apierr.BadRequest("empty_body", "The request body is required.")
		case strings.Contains(err.Error(), "http: request body too large"):
			return apierr.BadRequest("body_too_large", "The request body is too large.")
		default:
			return apierr.Wrap(err, http.StatusBadRequest, "invalid_json",
				fmt.Sprintf("The request body is not valid JSON: %s", err.Error()))
		}
	}
	if decoder.More() {
		return apierr.BadRequest("invalid_json", "The request body must contain a single JSON object.")
	}
	return nil
}

// requestMeta extracts the caller fingerprint stored with sessions/audit rows.
// net/http + chi's RealIP already resolve X-Forwarded-For into RemoteAddr.
func requestMeta(r *http.Request) service.RequestMeta {
	return service.RequestMeta{
		IPAddress: clientIP(r),
		UserAgent: truncate(r.UserAgent(), 255),
	}
}

func clientIP(r *http.Request) string {
	host, _, err := net.SplitHostPort(r.RemoteAddr)
	if err != nil {
		return r.RemoteAddr
	}
	return host
}

func truncate(v string, max int) string {
	if len(v) > max {
		return v[:max]
	}
	return v
}

// requiredString trims a field and rejects it when empty. `field` is used in
// the message so the admin panel can show which input is missing.
func requiredString(value, field string) (string, error) {
	value = strings.TrimSpace(value)
	if value == "" {
		return "", apierr.BadRequest("validation_failed", fmt.Sprintf("%s is required.", field))
	}
	return value, nil
}

