		return
	}
	if _, err := requiredString(body.ChallengeID, "challenge_id"); err != nil {
		writeErr(w, r, err)
		return
	}
	if _, err := requiredString(body.OTP, "otp"); err != nil {
		writeErr(w, r, err)
		return
	}

	result, err := h.svc.VerifyLoginOTP(r.Context(), service.VerifyOTPInput{
