)

// ---------------------------------------------------------------- admin store

type fakeAdminStore struct {
	admins map[string]*models.AdminUser
}

func newFakeAdminStore() *fakeAdminStore {
	return &fakeAdminStore{admins: map[string]*models.AdminUser{}}
}

func (f *fakeAdminStore) FindByID(_ context.Context, id string) (*models.AdminUser, error) {
	if a, ok := f.admins[id]; ok {
		return a, nil
	}
	return nil, models.ErrNotFound
}

func (f *fakeAdminStore) FindByIdentifier(_ context.Context, identifier string) (*models.AdminUser, error) {
	for _, a := range f.admins {
		if equalFold(a.Username, identifier) || equalFold(a.Email, identifier) {
			return a, nil
		}
	}
	return nil, models.ErrNotFound
}

func (f *fakeAdminStore) TouchLastLogin(_ context.Context, id string, at time.Time) error {
	if a, ok := f.admins[id]; ok {
		a.LastLoginAt = &at
	}
	return nil
}

func (f *fakeAdminStore) UpdatePassword(_ context.Context, id, passwordHash string, at time.Time) error {
	a, ok := f.admins[id]
	if !ok {
		return models.ErrNotFound
	}
	a.PasswordHash = passwordHash
	a.UpdatedAt = at
	return nil
}

// ------------------------------------------------------------------ 2FA store

type fakeTwoFAStore struct {
	rows []*models.TwoFactorConfig
}

func (f *fakeTwoFAStore) FindByAdminAndMethod(_ context.Context, adminID, method string) (*models.TwoFactorConfig, error) {
	for _, r := range f.rows {
		if r.AdminID == adminID && r.Method == method {
			return r, nil
		}
	}
	return nil, models.ErrNotFound
}

func (f *fakeTwoFAStore) ListByAdmin(_ context.Context, adminID string) ([]models.TwoFactorConfig, error) {
	var out []models.TwoFactorConfig
	for _, r := range f.rows {
		if r.AdminID == adminID {
			out = append(out, *r)
		}
	}
	return out, nil
}

func (f *fakeTwoFAStore) Upsert(_ context.Context, cfg *models.TwoFactorConfig) error {
	for _, r := range f.rows {
		if r.AdminID == cfg.AdminID && r.Method == cfg.Method {
			r.IsEnabled = cfg.IsEnabled
			r.ConfirmedAt = cfg.ConfirmedAt
			return nil
		}
	}
	f.rows = append(f.rows, cfg)
	return nil
}

func (f *fakeTwoFAStore) SetEnabled(_ context.Context, adminID, method string, enabled bool, at time.Time) error {
	for _, r := range f.rows {
		if r.AdminID == adminID && r.Method == method {
			r.IsEnabled = enabled
			if enabled {
				r.ConfirmedAt = &at
			}
			return nil
		}
	}
	return models.ErrNotFound
}

// ------------------------------------------------------------------ OTP store

type fakeOTPStore struct {
	mu   sync.Mutex
	rows []*models.OTPChallenge
}

func (f *fakeOTPStore) Create(_ context.Context, c *models.OTPChallenge) error {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.rows = append(f.rows, c)
	return nil
}

func (f *fakeOTPStore) FindByID(_ context.Context, id string) (*models.OTPChallenge, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	for _, r := range f.rows {
		if r.ID == id {
			return r, nil
		}
	}
	return nil, models.ErrNotFound
}

func (f *fakeOTPStore) FindLatestPending(_ context.Context, adminID, purpose string, at time.Time) (*models.OTPChallenge, error) {
	f.mu.Lock()
	defer f.mu.Unlock()

	var latest *models.OTPChallenge
	for _, r := range f.rows {
		if r.AdminID != adminID || r.Purpose != purpose || r.ConsumedAt != nil || !at.Before(r.ExpiresAt) {
			continue
		}
		if latest == nil || r.CreatedAt.After(latest.CreatedAt) {
			latest = r
		}
	}
	if latest == nil {
		return nil, models.ErrNotFound
	}
	return latest, nil
}

func (f *fakeOTPStore) CountCreatedSince(_ context.Context, adminID, purpose string, since time.Time) (int, error) {
	f.mu.Lock()
	defer f.mu.Unlock()

	count := 0
	for _, r := range f.rows {
		if r.AdminID == adminID && r.Purpose == purpose && !r.CreatedAt.Before(since) {
			count++
		}
	}
	return count, nil
}

func (f *fakeOTPStore) InvalidatePending(_ context.Context, adminID, purpose string, at time.Time) error {
	f.mu.Lock()
	defer f.mu.Unlock()
	for _, r := range f.rows {
		if r.AdminID == adminID && r.Purpose == purpose && r.ConsumedAt == nil {
			consumed := at
			r.ConsumedAt = &consumed
		}
	}
	return nil
}

func (f *fakeOTPStore) IncrementAttempts(_ context.Context, id string) (int, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	for _, r := range f.rows {
		if r.ID == id {
			r.AttemptCount++
			return r.AttemptCount, nil
		}
	}
	return 0, models.ErrNotFound
}

func (f *fakeOTPStore) Consume(_ context.Context, id string, at time.Time) (bool, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	for _, r := range f.rows {
		if r.ID == id {
			if r.ConsumedAt != nil {
				return false, nil
			}
			consumed := at
			r.ConsumedAt = &consumed
			return true, nil
		}
	}
	return false, nil
}

func (f *fakeOTPStore) DeleteOlderThan(_ context.Context, _ time.Time) error { return nil }

// -------------------------------------------------------------- refresh store

type fakeRefreshStore struct {
	mu   sync.Mutex
	rows []*models.RefreshToken
}

func (f *fakeRefreshStore) Create(_ context.Context, t *models.RefreshToken) error {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.rows = append(f.rows, t)
	return nil
}

func (f *fakeRefreshStore) FindByHash(_ context.Context, tokenHash string) (*models.RefreshToken, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	for _, r := range f.rows {
		if r.TokenHash == tokenHash {
			return r, nil
		}
	}
	return nil, models.ErrNotFound
}

func (f *fakeRefreshStore) Revoke(_ context.Context, id string, at time.Time) (bool, error) {
