 13 | 
 14 | // ChangePassword rotates the password of the signed-in admin. Every other
 15 | // session is revoked and a fresh pair is returned so the caller stays signed
 16 | // in on the current device.
 17 | func (s *AuthService) ChangePassword(ctx context.Context, adminID string, in ChangePasswordInput, meta RequestMeta) (*TokenPair, error) {
 18 | 	if err := s.validatePassword(in.NewPassword); err != nil {
 19 | 		return nil, err
 20 | 	}
 21 | 
 22 | 	admin, err := s.verifyAdminPassword(ctx, adminID, in.CurrentPassword)
 23 | 	if err != nil {
 24 | 		return nil, err
 25 | 	}
 26 | 
 27 | 	same, err := security.VerifyPassword(admin.PasswordHash, in.NewPassword)
 28 | 	if err != nil {
 29 | 		return nil, wrapErr(err, 500, "internal_error", "Stored credentials are unreadable.")
 30 | 	}
 31 | 	if same {
 32 | 		return nil, errSamePassword()
 33 | 	}
 34 | 
 35 | 	hash, err := security.HashPassword(in.NewPassword)
 36 | 	if err != nil {
 37 | 		return nil, wrapErr(err, 500, "internal_error", "Could not store the new password.")
 38 | 	}
 39 | 	if err := s.admins.UpdatePassword(ctx, admin.ID, hash, s.now()); err != nil {
 40 | 		return nil, err
 41 | 	}
 42 | 
 43 | 	// Kill every existing session, then start a new one for this device.
 44 | 	if _, err := s.refresh.RevokeAllForAdmin(ctx, admin.ID, s.now()); err != nil {
 45 | 		log.Printf("⚠️  auth: could not revoke sessions after password change: %v", err)
 46 | 	}
 47 | 	tokens, err := s.issueSession(ctx, admin, meta)
 48 | 	if err != nil {
 49 | 		return nil, err
 50 | 	}
 51 | 
 52 | 	s.auditEvent(ctx, admin.ID, models.AuditPasswordChanged, "", nil)
 53 | 	return tokens, nil
 54 | }
 55 | 
 56 | // ForgotPassword mails a reset code. It always reports success so the endpoint
 57 | // cannot be used to enumerate admin email addresses.
 58 | func (s *AuthService) ForgotPassword(ctx context.Context, in ForgotPasswordInput, meta RequestMeta) error {
 59 | 	emailAddress := strings.ToLower(strings.TrimSpace(in.Email))
 60 | 	if emailAddress == "" {
 61 | 		return nil
 62 | 	}
 63 | 
 64 | 	admin, err := s.admins.FindByIdentifier(ctx, emailAddress)
 65 | 	if err != nil {
 66 | 		if errors.Is(err, models.ErrNotFound) {
 67 | 			log.Printf("🔐 auth: password reset requested for unknown address %s", emailAddress)
 68 | 			return nil
 69 | 		}
 70 | 		return err
 71 | 	}
 72 | 	if !admin.IsActive {
 73 | 		return nil
 74 | 	}
 75 | 
 76 | 	if _, err := s.issueOTP(ctx, admin, models.OTPPurposePasswordReset, meta); err != nil {
 77 | 		// Rate limiting is the only failure worth surfacing; mail problems are
 78 | 		// reported as success to keep the response indistinguishable.
 79 | 		var apiErr *apierr.Error
 80 | 		if errors.As(err, &apiErr) && apiErr.Status == 429 {
 81 | 			return err
 82 | 		}
 83 | 		log.Printf("⚠️  auth: reset mail failed for admin %s: %v", admin.ID, err)
 84 | 		return nil
 85 | 	}
 86 | 	s.auditEvent(ctx, admin.ID, models.AuditPasswordResetAsked, "", nil)
 87 | 	return nil
 88 | }
 89 | 
 90 | // ResetPassword completes the reset flow and signs the admin in.
 91 | func (s *AuthService) ResetPassword(ctx context.Context, in ResetPasswordInput, meta RequestMeta) (*LoginResult, error) {
 92 | 	if err := s.validatePassword(in.NewPassword); err != nil {
 93 | 		return nil, err
 94 | 	}
 95 | 
 96 | 	challenge, err := s.loadChallenge(ctx, in.ChallengeID, models.OTPPurposePasswordReset)
 97 | 	if err != nil {
 98 | 		return nil, err
 99 | 	}
100 | 
101 | 	admin, err := s.checkOTP(ctx, challenge, in.OTP)
102 | 	if err != nil {
103 | 		return nil, err
104 | 	}
105 | 
106 | 	hash, err := security.HashPassword(in.NewPassword)
107 | 	if err != nil {
108 | 		return nil, wrapErr(err, 500, "internal_error", "Could not store the new password.")
109 | 	}
110 | 	if err := s.admins.UpdatePassword(ctx, admin.ID, hash, s.now()); err != nil {
111 | 		return nil, err
112 | 	}
113 | 	if _, err := s.refresh.RevokeAllForAdmin(ctx, admin.ID, s.now()); err != nil {
114 | 		log.Printf("⚠️  auth: could not revoke sessions after password reset: %v", err)
115 | 	}
116 | 	if err := s.admins.TouchLastLogin(ctx, admin.ID, s.now()); err != nil {
117 | 		log.Printf("⚠️  auth: could not record last login for admin %s: %v", admin.ID, err)
118 | 	}
119 | 
120 | 	tokens, err := s.issueSession(ctx, admin, meta)
121 | 	if err != nil {
122 | 		return nil, err
123 | 	}
124 | 	s.auditEvent(ctx, admin.ID, models.AuditPasswordReset, "", nil)
125 | 	return &LoginResult{Tokens: tokens, Admin: adminView(admin)}, nil
126 | }
127 | 
128 | // validatePassword enforces the password policy (AUTH_MIN_PASSWORD_LENGTH plus
129 | // the shared mix rule) and maps violations to the API error.
130 | func (s *AuthService) validatePassword(password string) error {
131 | 	if err := security.ValidatePassword(password, s.cfg.MinPasswordLength); err != nil {
132 | 		return errWeakPassword("Password must " + err.Error() + ".")
133 | 	}
134 | 	return nil
135 | }

