 12 | 
 13 | // emailTwoFAConfig resolves whether email OTP must be used for this admin.
 14 | //
 15 | // Rules:
 16 | //   - a row with is_enabled = 1 means 2FA is on;
 17 | //   - when AUTH_2FA_REQUIRED=true the second factor can never be skipped: a
 18 | //     missing row is auto-provisioned (no enrollment is needed for email OTP)
 19 | //     and a disabled row is re-enabled;
 20 | //   - when AUTH_2FA_REQUIRED=false the admin's own setting decides.
 21 | //
 22 | // The bool return value reports whether an OTP must be sent.
 23 | func (s *AuthService) emailTwoFAConfig(ctx context.Context, admin *models.AdminUser) (*models.TwoFactorConfig, bool, error) {
 24 | 	cfg, err := s.twoFA.FindByAdminAndMethod(ctx, admin.ID, models.TwoFAMethodEmailOTP)
 25 | 	switch {
 26 | 	case err == nil:
 27 | 		if cfg.IsEnabled {
 28 | 			return cfg, true, nil
 29 | 		}
 30 | 		if !s.cfg.TwoFARequired {
 31 | 			return cfg, false, nil
 32 | 		}
 33 | 
 34 | 		now := s.now()
 35 | 		cfg.IsEnabled = true
 36 | 		cfg.ConfirmedAt = &now
 37 | 		if err := s.twoFA.SetEnabled(ctx, admin.ID, cfg.Method, true, now); err != nil {
 38 | 			return nil, false, err
 39 | 		}
 40 | 		s.auditEvent(ctx, admin.ID, models.AuditTwoFAEnabled, "enforced_by_config", nil)
 41 | 		return cfg, true, nil
 42 | 
 43 | 	case errors.Is(err, models.ErrNotFound):
 44 | 		if !s.cfg.TwoFARequired {
 45 | 			return nil, false, nil
 46 | 		}
 47 | 		now := s.now()
 48 | 		cfg = &models.TwoFactorConfig{
 49 | 			ID:          ids.New(),
 50 | 			AdminID:     admin.ID,
 51 | 			Method:      models.TwoFAMethodEmailOTP,
 52 | 			IsEnabled:   true,
 53 | 			ConfirmedAt: &now,
 54 | 			CreatedAt:   now,
 55 | 		}
 56 | 		if err := s.twoFA.Upsert(ctx, cfg); err != nil {
 57 | 			return nil, false, err
 58 | 		}
 59 | 		s.auditEvent(ctx, admin.ID, models.AuditTwoFAEnabled, "auto_provisioned", nil)
 60 | 		return cfg, true, nil
 61 | 
 62 | 	default:
 63 | 		return nil, false, err
 64 | 	}
 65 | }
 66 | 
 67 | // TwoFAStatus reports the effective 2FA state: Enabled is true when the
 68 | // second factor is required either by server policy or by the admin setting.
 69 | func (s *AuthService) TwoFAStatus(ctx context.Context, admin *models.AdminUser) (*TwoFAStatus, error) {
 70 | 	status := &TwoFAStatus{
 71 | 		Required: s.cfg.TwoFARequired,
 72 | 		Method:   models.TwoFAMethodEmailOTP,
 73 | 		Email:    security.MaskEmail(admin.Email),
 74 | 	}
 75 | 
 76 | 	cfg, err := s.twoFA.FindByAdminAndMethod(ctx, admin.ID, models.TwoFAMethodEmailOTP)
 77 | 	if err != nil {
 78 | 		if errors.Is(err, models.ErrNotFound) {
 79 | 			status.Enabled = s.cfg.TwoFARequired
 80 | 			return status, nil
 81 | 		}
 82 | 		return nil, err
 83 | 	}
 84 | 
 85 | 	status.Enabled = cfg.IsEnabled || s.cfg.TwoFARequired
 86 | 	status.ConfirmedAt = cfg.ConfirmedAt
 87 | 	created := cfg.CreatedAt
 88 | 	status.UpdatedAt = &created
 89 | 	return status, nil
 90 | }
