 92 | // TwoFAStatusByAdminID is the handler-friendly variant of TwoFAStatus.
 93 | func (s *AuthService) TwoFAStatusByAdminID(ctx context.Context, adminID string) (*TwoFAStatus, error) {
 94 | 	admin, err := s.adminFor(ctx, adminID)
 95 | 	if err != nil {
 96 | 		return nil, err
 97 | 	}
 98 | 	return s.TwoFAStatus(ctx, admin)
 99 | }
