101 | // EnableEmailOTP turns the email second factor on (password re-confirmation
102 | // required) and returns the fresh status.
103 | func (s *AuthService) EnableEmailOTP(ctx context.Context, adminID string, in PasswordConfirmationInput) (*TwoFAStatus, error) {
104 | 	admin, err := s.verifyAdminPassword(ctx, adminID, in.Password)
105 | 	if err != nil {
106 | 		return nil, err
107 | 	}
108 | 
109 | 	now := s.now()
110 | 	cfg := &models.TwoFactorConfig{
111 | 		ID:          ids.New(),
112 | 		AdminID:     admin.ID,
113 | 		Method:      models.TwoFAMethodEmailOTP,
114 | 		IsEnabled:   true,
115 | 		ConfirmedAt: &now,
116 | 		CreatedAt:   now,
117 | 	}
118 | 	if err := s.twoFA.Upsert(ctx, cfg); err != nil {
119 | 		return nil, err
120 | 	}
121 | 	s.auditEvent(ctx, admin.ID, models.AuditTwoFAEnabled, "admin_setting", nil)
122 | 	return s.TwoFAStatus(ctx, admin)
123 | }
