125 | // DisableEmailOTP turns the second factor off. It refuses when the server
126 | // enforces 2FA (AUTH_2FA_REQUIRED=true) so a compromised session cannot strip
127 | // the protection.
128 | func (s *AuthService) DisableEmailOTP(ctx context.Context, adminID string, in PasswordConfirmationInput) error {
129 | 	if s.cfg.TwoFARequired {
130 | 		return errTwoFAEnforced()
131 | 	}
132 | 
133 | 	admin, err := s.verifyAdminPassword(ctx, adminID, in.Password)
134 | 	if err != nil {
135 | 		return err
136 | 	}
137 | 
138 | 	if err := s.twoFA.SetEnabled(ctx, admin.ID, models.TwoFAMethodEmailOTP, false, s.now()); err != nil {
139 | 		if errors.Is(err, models.ErrNotFound) {
140 | 			return errTwoFANotConfigured()
141 | 		}
142 | 		return err
143 | 	}
144 | 	s.auditEvent(ctx, admin.ID, models.AuditTwoFADisabled, "admin_setting", nil)
145 | 	return nil
146 | }
