148 | // verifyAdminPassword re-authenticates a signed-in admin for sensitive actions.
149 | func (s *AuthService) verifyAdminPassword(ctx context.Context, adminID, password string) (*models.AdminUser, error) {
150 | 	admin, err := s.admins.FindByID(ctx, adminID)
151 | 	if err != nil {
152 | 		if errors.Is(err, models.ErrNotFound) {
153 | 			return nil, errInvalidCredentials()
154 | 		}
155 | 		return nil, err
156 | 	}
157 | 	if !admin.IsActive {
158 | 		return nil, errAccountDisabled()
159 | 	}
160 | 	if password == "" {
161 | 		return nil, errInvalidPassword()
162 | 	}
163 | 
164 | 	ok, err := security.VerifyPassword(admin.PasswordHash, password)
165 | 	if err != nil {
166 | 		return nil, wrapErr(err, 500, "internal_error", "Stored credentials are unreadable.")
167 | 	}
168 | 	if !ok {
169 | 		log.Printf("⚠️  auth: password re-confirmation failed for admin %s", admin.ID)
170 | 		return nil, errInvalidPassword()
171 | 	}
172 | 	return admin, nil
173 | }

