 45 | // NewAuthService builds the service.
 46 | func NewAuthService(deps Deps) *AuthService {
 47 | 	now := deps.Now
 48 | 	if now == nil {
 49 | 		now = func() time.Time { return time.Now().UTC() }
 50 | 	}
 51 | 	return &AuthService{
 52 | 		admins:       deps.Admins,
 53 | 		twoFA:        deps.TwoFA,
 54 | 		otps:         deps.OTPs,
 55 | 		refresh:      deps.Refresh,
 56 | 		audit:        deps.Audit,
 57 | 		mailer:       deps.Mailer,
 58 | 		tokens:       deps.Tokens,
 59 | 		cfg:          deps.Cfg,
 60 | 		now:          now,
 61 | 		loginLimiter: security.NewLimiter(deps.Cfg.LoginMaxAttempts, deps.Cfg.LoginWindow),
 62 | 	}
 63 | }
 64 | 
 65 | // Login validates the password. When email-OTP 2FA applies it mails a code and
 66 | // returns a challenge; otherwise it signs the admin in directly (only possible
 67 | // when AUTH_2FA_REQUIRED=false and the method was disabled).
 68 | func (s *AuthService) Login(ctx context.Context, in LoginInput, meta RequestMeta) (*LoginResult, error) {
 69 | 	identifier := strings.TrimSpace(in.Identifier)
 70 | 	if identifier == "" || in.Password == "" {
 71 | 		return nil, errInvalidCredentials()
 72 | 	}
 73 | 
 74 | 	limitKey := security.ClientKey(identifier, meta.IPAddress)
 75 | 	if !s.loginLimiter.Allow(limitKey) {
 76 | 		s.auditEvent(ctx, "", models.AuditLoginFailed, "rate_limited", map[string]any{"identifier": identifier})
 77 | 		return nil, errRateLimited(int(s.loginLimiter.RetryAfter(limitKey).Seconds()) + 1)
 78 | 	}
 79 | 
 80 | 	admin, err := s.admins.FindByIdentifier(ctx, identifier)
 81 | 	if err != nil {
 82 | 		if errors.Is(err, models.ErrNotFound) {
 83 | 			// Burn the same CPU as a real verification so the response time
 84 | 			// does not disclose whether the account exists.
 85 | 			_, _ = security.VerifyPassword(security.DummyPasswordHash, in.Password)
 86 | 			s.loginLimiter.RegisterFailure(limitKey)
 87 | 			s.auditEvent(ctx, "", models.AuditLoginFailed, "unknown_identifier", map[string]any{"identifier": identifier})
 88 | 			return nil, errInvalidCredentials()
 89 | 		}
 90 | 		return nil, err
 91 | 	}
 92 | 
 93 | 	if !admin.IsActive {
 94 | 		s.loginLimiter.RegisterFailure(limitKey)
 95 | 		s.auditEvent(ctx, admin.ID, models.AuditLoginFailed, "inactive", nil)
 96 | 		return nil, errAccountDisabled()
 97 | 	}
 98 | 
 99 | 	ok, err := security.VerifyPassword(admin.PasswordHash, in.Password)
100 | 	if err != nil {
101 | 		return nil, wrapErr(err, 500, "internal_error", "Stored credentials are unreadable.")
102 | 	}
103 | 	if !ok {
104 | 		s.loginLimiter.RegisterFailure(limitKey)
105 | 		s.auditEvent(ctx, admin.ID, models.AuditLoginFailed, "bad_password", nil)
106 | 		return nil, errInvalidCredentials()
107 | 	}
108 | 	s.loginLimiter.Reset(limitKey)
109 | 
110 | 	// Opportunistically upgrade hashes produced with weaker parameters.
111 | 	if security.NeedsRehash(admin.PasswordHash) {
112 | 		if hash, err := security.HashPassword(in.Password); err == nil {
